//! Environment fragments generator (/etc/profile.d/appdepot.d/*.sh).

pub fn generate_fragment(app_id: &str, install_dir: &str) -> String {
    format!(
        "# Generated by AppDepot for {app_id}\nexport {var}_HOME=\"{dir}\"\nexport PATH=\"${var}_HOME/bin:$PATH\"\n",
        app_id = app_id,
        var = app_id.to_uppercase().replace('-', "_"),
        dir = install_dir
    )
}
